// Availability x Performance proxy from twin KPIs.
// Nominal rate: slowest stage (packer, 0.6 min/unit) -> 100 units/h.
const k = msg.payload;
const nominalRate = 100;
const performance = Math.min(1, k.throughput_per_h / nominalRate);
const availability = k.time_min > 0 ? Math.max(0, 1 - k.changeover_min / k.time_min) : 1;
msg.payload = {time_min: k.time_min, units_out: k.units_out, throughput_per_h: k.throughput_per_h, availability: +availability.toFixed(3), performance: +performance.toFixed(3), oee_proxy: +(availability * performance).toFixed(3), energy: k.energy, tardiness_min: k.tardiness_min};
return msg;

const d = msg.payload;
const alerts = d.products.filter(p => p.alert).map(p => `product ${p.product} late by ${p.deviation_min} min vs plan`);
if (d.flow_alert) alerts.push(`flow behind plan by ${-d.flow_gap_units} units`);
if (alerts.length === 0) return null;
msg.payload = {time_min: d.time_min, alerts};
return msg;
